        float e = sdBox(uv0,vec2(size-.2,size-.2));

        float y = sdBox(uv3,vec2(sq,sq));
        float z = sdBox(uv4,vec2(sq,sq));


        z = abs(z);
        z = smoothstep(0.,.1,z);
